def minDeletionCost(s, cost, t):
    n = len(t)
    NEG = -1
    best = [NEG] * (n + 1)
    best[0] = 0
    for i, ch in enumerate(s):
        c = cost[i]
        for j in range(min(i + 1, n), 0, -1):
            if t[j - 1] == ch and best[j - 1] >= 0:
                v = best[j - 1] + c
                if v > best[j]:
                    best[j] = v
    if best[n] < 0:
        return -1
    return sum(cost) - best[n]
